from pathlib import Path
import subprocess,sys

def git(*args):
    return subprocess.check_output(['git',*args],text=True).strip()
receipt=Path('external/review.txt')
reviewed=receipt.is_file() and receipt.read_text()=='approved local-60\n'
command=sys.argv[1] if len(sys.argv)>1 else 'status'
if command=='status':
    print('PR local-60; base master; head feature/export; review '+('approved' if reviewed else 'missing'))
    print('base='+git('rev-parse','master')+' head='+git('rev-parse','feature/export'))
elif command=='merge':
    if not reviewed: raise SystemExit('independent review missing')
    git('switch','master')
    git('merge','--ff-only','feature/export')
    print('local simulated PR merged: '+git('rev-parse','master'))
else: raise SystemExit('usage: python3 merge-sim.py status|merge')
